script:
frappe.ui.form.on('VSO', {
    refresh(frm) {
        if (frm.is_new()) return;
        frm.add_custom_button(__('Sync Customer'), () => {
            frappe.call({
                method: 'autoom_dealer.api.integration.sync_customer',
                args: { source_doctype: 'VSO', source_name: frm.doc.name },
                freeze: true,
                callback(r) {
                    frappe.msgprint(__('Customer synced: {0}', [r.message.customer]));
                    frm.reload_doc();
                }
            });
        }, __('Autoom'));
        frm.add_custom_button(__('Create Sales Order'), () => {
            frappe.call({
                method: 'autoom_dealer.api.integration.create_sales_order',
                args: { vso_name: frm.doc.name },
                freeze: true,
                callback(r) {
                    const msg = r.message.action === 'already_linked'
                        ? __('Already linked: {0}', [r.message.sales_order])
                        : __('Sales Order created: {0}', [r.message.sales_order]);
                    frappe.msgprint(msg);
                    frm.reload_doc();
                }
            });
        }, __('Autoom'));
    }
});

frappe.ui.form.on('Prospect Booking Form', {
    refresh(frm) {
        if (frm.is_new()) return;
        frm.add_custom_button(__('Sync Customer'), () => {
            frappe.call({
                method: 'autoom_dealer.api.integration.sync_customer',
                args: { source_doctype: 'Prospect Booking Form', source_name: frm.doc.name },
                freeze: true,
                callback(r) {
                    frappe.msgprint(__('Customer synced: {0}', [r.message.customer]));
                    frm.reload_doc();
                }
            });
        }, __('Autoom'));
    }
});
